-- GENERATED by `wfj generate` from data/gossip/gossip-26.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["26028189c7a6fb9c"] = { "Questioni di natura così ufficiale si sbrigano solo a Darnassus. Devi recarti lì per avviare le pratiche per la creazione della tua gilda.", "." },
  ["2609a123669b9401"] = { "Gli umani hanno bisogno del tuo aiuto nella loro lotta contro i Reietti al ⟦Arathi Basin=Bacino d'Arathi⟧. Va' alla Hall of Arms e parla con il loro rappresentante, Donal Osgood.", "." },
  ["261669795c7f82fd"] = { "Ah, <uno/una> dei nostri. È bello vedere che il nostro numero cresce tanto in fretta che non riesco più a ricordare le facce di tutti i membri.\n\nQuello sciocco di Thrall crede che io mi stia impegnando per ripulire l'immagine degli stregoni e dimostrare che siamo suoi servitori. Idiota! La Legione Infuocata ridurrà in cenere questo mondo intero, dopo averlo prosciugato del tutto.", "." },
  ["261cb23e27381f5d"] = { "Buona giornata a te.", "." },
  ["261d9ccbcc70175d"] = { "Le nostre unità veterane stanno lasciando il campo. Ci servono altri rifornimenti!", "." },
  ["26218a8ae271f7f6"] = { "Una sacerdotessa di nome Laurna Morninglight vive a Dolanaar. Credo che la troverai appena a nord della locanda.", "." },
  ["26287b2fccdc5f21"] = { "Fatti avanti e bagnati la gola.", "." },
  ["262ba9d40cbc8032"] = { "Tu magari pensa che questo è solo mio bastone da passeggio, amico. È proprio quello che io voglio che tu pensa.", "." },
  ["262d6d77ad428b94"] = { "Il lavoro al porto è aperto a tutti, ma la tua incolumità è una tua responsabilità.", "." },
  ["262fd3c2a1f18887"] = { "Ah sì, è vero.\n\nDunque, eccoci lì a invadere i livelli superiori dei ⟦Blackrock Spire=Bastioni di Roccianera⟧, contro il loro signore e capo; questo prima di Drakkisath. Non molto furbo, se vuoi il mio parere, ma il nostro capo, Anthion Harmon, l'hai conosciuto, è sempre stato uno che amava le sfide.\n\nSorprendentemente, tutto andò secondo i piani, fino al momento in cui stavamo strappando il libro degli incantesimi di Valthalak dalle sue dita rigide. È lì che tutto è andato a rotoli.\n\nDevo continuare? Mi sembra che tu abbia lo sguardo sempre più vitreo.", "." },
  ["2633648e1607d1f9"] = { "Marduk, prendi la scatola e posala davanti a me!", "." },
  ["26338eb05890f84d"] = { "%s colpisce la tua fiala di raccolta. Il bagliore verde ti avvolge. Non hai una gran bella cera, amico.", "." },
  ["26367f0f53a4c2af"] = { "Abbiamo udito le tue richieste e siamo d'accordo... il tuo intento è nobile. Purificheremo le tue acque. Va' con la nostra benedizione, <Sciamano/Sciamana>.", "." },
  ["263960090094af41"] = { "Questo è il campo di battaglia della ⟦Alterac Valley=Valle d'Alterac⟧. Al momento le due fazioni sono in conflitto.", "." },
  ["263dbea62b61c265"] = { "⟦Polar Bracers=Bracciali Polari⟧.", "." },
  ["263f195fd35937e2"] = { "Che posso fare per te?", "." },
  ["2646e1f47394ef28"] = { "Ringrazio i miei antenati: qualcuno è venuto ad aiutarmi. Hai la chiave che mi libererà?", "." },
  ["2648cdc46a647dc5"] = { "La mia abilità nel creare pozioni è inferiore alla tua. Sei <pronto/pronta> per parlare con Ainethil, proprio lì. Capirà che è il momento di istruirti ancora.", "." },
  ["265427cfe485e678"] = { "La mischia è finita!", "." },
  ["26547f1924ffe11d"] = { "Vorrei inserire il codice segreto per ricevere la mia mascotte Zergling.", "." },
  ["26565a77af12fbc5"] = { "Cerchi addestramento, eh? Potrei addestrarti meglio di chiunque altro a ⟦Stormwind=Roccavento⟧, ma la guardia me lo proibisce. Credo che dovrai accontentarti di uno di quei vecchi arnesi che bazzicano la caserma o la Pig and Whistle Tavern nella Old Town.", "." },
  ["26576c5ead3bb426"] = { "Rimane solo un dovere...", "." },
  ["2657db49152c252b"] = { "Dov'è l'assistente di Tirth?", "." },
  ["265ca04b3fb68411"] = { "Il Re dei Lich ci ha portato guerra dal gelido nord, e soltanto noi dell'⟦Argent Dawn=Alba d'Argento⟧ gli sbarriamo la strada.", "." },
  ["266a6d28d1dfc7f5"] = { "Devo... RESISTERE!", "." },
  ["266b508ae6718f01"] = { "Sei <diventato/diventata> <un/una> <cacciatore/cacciatrice> coi fiocchi, {name}! Non solo hai dimostrato le tue capacità, hai anche battuto Daryl, e per me questo vale punti extra!\n\nQui sarai sempre <benvenuto/benvenuta>.", "." },
  ["267c98ae4562dce7"] = { "Incredibile! Straordinario! Non so nemmeno cosa voglia dire!", "." },
  ["2685db3f9e993e9d"] = { "La West Frostwolf Tower è sotto attacco! Se nessuno interviene, l'⟦Alliance=Alleanza⟧ la distruggerà!", "." },
  ["26887e6be75e7808"] = { "Devi essere in rapporti amichevoli con i tauren di ⟦Thunder Bluff=Picco del Tuono⟧ prima che io ti insegni a cavalcare, {class}.", "." },
  ["268dc64b8d54160d"] = { "Il ⟦Snowfall Graveyard=Cimitero di Nevealta⟧ è sotto attacco! Se nessuno interviene, l'⟦Alliance=Alleanza⟧ lo conquisterà!", "." },
  ["26905cf76e76e088"] = { "Ragazzi e ragazze, bambini di tutte le età: è arrivata la ⟦Darkmoon Faire=Fiera di Lunacupa⟧! Urrà!", "." },
  ["2690848c575297f4"] = { "Ci sono, {name}. Troviamo la mia attrezzatura e andiamocene. Credo di sapere dov'è.", "." },
  ["269e802dd2aa73d2"] = { "La fine si avvicina! Proprio mentre parliamo, le ultime scorte vengono spedite a ⟦Silithus=Silitus⟧ e dovrebbero arrivare entro un giorno. Una volta lì, non ho dubbi che tutto verrà assemblato in fretta, e poi attenderemo il rintocco del gong alle porte di ⟦Ahn'Qiraj=Ahn'qiraj⟧ per dare inizio alla guerra. Non vedo l'ora di analizzare se i nostri preparativi faranno la differenza.", "." },
  ["269f9cd4ead2d6d6"] = { "Saluti. Il mio compito è custodire l'ingresso. Se le Plates of Uldum non sono già integrate nel tuo set di dischi, non consentirò l'accesso al complesso di Uldum.", "." },
  ["26a048dad01ded29"] = { "Non prevedo complicazioni in questa... Aspetta! Cos'è questo?", "." },
  ["26a38eac52a323dd"] = { "Il demone si è liberato! Presto, dobbiamo trattenerlo!", "." },
  ["26a775cc0a226d03"] = { "Nella mia vita precedente abitavo qui vicino. Ogni tanto vago ancora per i campi della fattoria della mia infanzia. Mi riempie di tristezza vedere coloro che conoscevo e amavo trascinarsi in giro come schiavi senza mente. Mi fa male, ma è proprio quel dolore a darmi forza e uno scopo.", "." },
  ["26a9fc9d19ac1a8c"] = { "<Un/Una> {race} da nulla come te, {name}, non ha alcun diritto di camminare su queste terre!", "." },
  ["26b972742aafa448"] = { "NON PUÒ ESSERE!!", "." },
  ["26ba31492039da7e"] = { "Vedetta, informa Althea che una terribile minaccia si sta radunando contro la nostra città. Dobbiamo prepararci!", "." },
  ["26bda30ddc190222"] = { "Ok, andiamocene, presto presto! Cerca di starmi dietro. Sto per darmela a gambe.", "." },
  ["26bde686b21b60c3"] = { "La tua ⟦Horde=Orda⟧ non è nulla per i Kolkar!", "." },
  ["26cd2f8854be0afb"] = { "Ti seguirò fino all'accampamento. Se parli con il mio assistente, Hornizz, ti darà la tua paga.", "." },
  ["26ce8e1581f800f5"] = { "Rimpianto. È tutto ciò che mi resta. Una sola decisione sbagliata e tante conseguenze orribili. Se solo avessi aspettato quegli ordini. Forse avrebbero descritto gli orrori che ci attendevano in quelle terre maledette! Forse dovevano assegnarci a un altro incarico? Alla fine, è stata colpa mia. È stata tutta colpa mia.", "." },
  ["26d1a20a65292879"] = { "Io, addestrarti? Ma dai, sappiamo tutti e due che non posso. È colpa dell'insegnamento, capisci? Le mie abilità ne risentono. Se vuoi addestrarti, va' dal dottor Herbert Halsey, un Reietto nell'Apothecarium di ⟦Undercity=Sepulcra⟧.", "." },
  ["26d689faa7dc7405"] = { "Che razza di combattimento era quello? Dovrei cacciare tutte le vostre pellacce inutili dalla squadra e dalla guardia!", "." },
  ["26dc78c3b5e4fa19"] = { "Al lavoro, buoni a nulla!", "." },
  ["26dd181d46ec1885"] = { "Quello è il nostro tesoro, razza di incapace!", "." },
  ["26ddf1b9d9fc498b"] = { "Troverai di sicuro Maxan Anvol a farsi qualche bicchiere nella ⟦Thunderbrew Distillery=Distilleria Birratuono⟧. Perché non vai a farti una pinta e vedi se ti insegna qualcosa di nuovo?", "." },
  ["26e3ccc34a694718"] = { "Abbiamo una discreta scorta di materiali per la ricostruzione, ma ce ne servono ancora molti prima di poter riparare del tutto la ⟦Frostwolf Keep=Rocca dei Lupi Bianchi⟧.", "." },
  ["26e83a2aebe6eed2"] = { "Questo spirito aleggia sopra il suo corpo caduto. I suoi occhi spettrali ti trapassano mentre fissa un punto lontano...", "." },
  ["26ed8e456596df69"] = { "Attenzione! {name} ci è addosso!", "." },
  ["26eec5962104e9ff"] = { "Perché dovevo ritrovarmi con questa scusa di <stregone/strega> ripugnante e debole?", "." },
  ["26f156ae394817b2"] = { "%s si protende verso il capitano Beltis mentre lei cade.", "." },
  ["26fed8b845bd4a98"] = { "Posso insegnarti i segreti del ⟦Tiger Riding=Cavalca-Tigre⟧, a patto che tu abbia abbastanza oro per pagare la lezione!", "." },
})
